% =====================================================================
\chapter{Fasern und Werkstoffe: vom St\"angel zum Zwirn}
% =====================================================================

\section{\"Ubersicht: Faserquellen und ihr Aufwand}

\begin{longtable}{p{35mm}p{30mm}p{45mm}}
\caption{Tab.\ 7.1 -- Faserpflanzen und Ernte-Fenster}\\
\toprule
Pflanze & Ernte & Nutzen \\
\midrule
\endfirsthead
\caption[]{Tab.\ 7.1 -- Faserpflanzen (Fortsetzung)}\\
\toprule
Pflanze & Ernte & Nutzen \\
\midrule
\endhead
\bottomrule
\endlastfoot
Brennnessel & Juli--August, alte St\"angel & Zwirn, Schnur, Netzgarn \\
Lindenbast (Land) & Fr\"uhjahr, gef\"allte \"Aste & grobes Bindematerial,
Seil \\
Weidenruten (Land) & Winter, einj\"ahrig & K\"orbe, Z\"aune, Binden \\
Schilf / Rohrkolben & Herbst--Winter & Matte, Dach, Isolierschicht \\
\end{longtable}

\begin{konzept}{7.1 -- Nesselfaser: R\"osten und Brechen}
\textbf{Definition:} Die Fasern der Brennnessel-St\"angel liegen in der
\"au\ss{}eren Rinde; nach Wasser-R\"osten (F\"aulung der Weichteile) und
Brechen bleibt ein fester, seidiger Faserstrang \"ubrig.

\textbf{Dreifache Pr\"ufung vor der Aufnahme:}
\begin{schritte}
\item Ernte nur bl\"uhende, alte St\"angel \"uber 50~cm im Juli--August
      (junger St\"angel hat zu wenig Faser).
\item St\"angel b\"undeln (Daumendicke B\"undel), 2--3~Wochen in stehendem
      Wasser legen oder feucht in Gras einwickeln -- bis die Rinde sich
      l\"ost (Geruch pr\"ufen: modrig, nicht faulig-stinkend).
\item St\"angel trocknen, dann \"uber ein Brett brechen und die Bruchst\"ucke
      der Rinde abstreifen -- \"ubrig bleibt der Faserstrang.
\end{schritte}

\textbf{Dreifache Bewertung nach bestandener Pr\"ufung:}
\begin{schritte}
\item Zugprobe: ein Faserstrang h\"alt das eigene Gewicht eines 1-kg-St\"ucks?
      Rei\ss{}t er sofort: R\"ostzeit verl\"angern.
\item Fasern glatt und seidig, nicht br\"uchig-trocken?
\item Ertrag notiert: Faustwert 10--20~g nutzbare Faser je 100~g St\"angel
      -- \"ortlich pr\"ufen.
\end{schritte}

\textbf{Grenzen:} Nesselfaser ist fein aber arbeitsaufwendig -- f\"ur gro\ss{}e
Seile ist Lindenbast schneller. Das R\"osten braucht Wasser und zwei bis
drei Wochen Vorlauf.
\end{konzept}

\begin{konzept}{7.2 -- Zwirn drehen: die Handspinne}
\textbf{Definition:} Aus Faserstr\"angen entsteht Zwirn durch wiederholtes
Drehen und \"Uberlappen; Werkzeug ist ein glatter Stein oder Stab als
Spindel.

\textbf{Dreifache Pr\"ufung vor der Aufnahme:}
\begin{schritte}
\item Faserstr\"ang in 20--30~cm-St\"ucke sortieren, je St\"uck d\"unner als
      ein Bleistift.
\item Ein Ende zwischen Daumen und Zeigefinger rollen, bis es sich
      verdreht; mit dem zweiten St\"uck \"uberlappen und weiterrollen --
      \"Uberlappung mind.\ 5~cm.
\item Fertigen Zwirn auf die Spindel wickeln und mit einem Einzelstrang
      die Lastprobe machen: 2~kg h\"alten ohne Rei\ss{}en (Faustwert --
      \"ortlich pr\"ufen).
\end{schritte}

\textbf{Dreifache Bewertung nach bestandener Pr\"ufung:}
\begin{schritte}
\item Drehung gleichm\"a\ss{}ig? Lockerer Zwirn rei\ss{}t an der ersten
      \"Uberlappung.
\item Zwei Einzelstr\"ange gegenseitig verdrillt (S-Zwirn) f\"ur
      belastbares Garn?
\item Erste 5~m in Vorlage A.7 dokumentiert mit Lastprobe-Ergebnis?
\end{schritte}

\textbf{Grenzen:} Handgedrehter Zwirn erreicht keine Maschinenfestigkeit --
f\"ur Traglasten \"uber K\"orpergewicht immer doppelt verdrehen oder
Lindenbast nehmen.
\end{konzept}

\begin{figure}[ht]
\centering
\includesvg[width=\textwidth]{illustrationen/abb-7-1}
\caption{Abb.\ 7.1 -- Nesselfaser in vier Schritten: Ernte, R\"osten,
Brechen, Zwirn}
\end{figure}

\begin{baustein}
Merks\"atze: Junger St\"angel, wenig Faser -- ernte alt. R\"ostgeruch modrig,
nicht stinkend. Wer Last will, verdreht doppelt.
\end{baustein}

\section{Kapitel-Checkliste: Fasern und Werkstoffe}

\begin{checkliste}
\item Ich habe nur alte, bl\"uhende Nesseln \"uber 50~cm geerntet.
\item Ich habe 2--3~Wochen ger\"ostet und den Geruch t\"aglich gepr\"uft.
\item Ich habe die St\"angel vollst\"andig getrocknet vor dem Brechen.
\item Ich habe Zwirn mit 5~cm \"Uberlappung gedreht und die Lastprobe
      durchgef\"uhrt.
\item Ich habe Traglasten nur mit doppelt verdrilltem Zwirn oder Bast
      aufgeh\"angt.
\item Ich habe Ertrag und Lastprobe in Vorlage A.7 notiert.
\end{checkliste}

% =====================================================================
\chapter{Dach-Pflanzen und Anbau: vom Wildwuchs zum Wildgarten}
% =====================================================================

\section{\"Ubersicht: Was der Bewuchs am Haus leisten kann}

\begin{longtable}{p{35mm}p{45mm}p{35mm}}
\caption{Tab.\ 8.1 -- Pflanzen als Baustoff und Anbaufl\"ache}\\
\toprule
Zweck & Pflanze / Material & Arbeit \\
\midrule
\endfirsthead
\caption[]{Tab.\ 8.1 -- Dach-Pflanzen (Fortsetzung)}\\
\toprule
Zweck & Material & Arbeit \\
\midrule
\endhead
\bottomrule
\endlastfoot
Dachdeckung & Schilf, Rohrkolben, Stroh von Wildgr\"asern & B\"undel binden,
l\"ags in Lagen \\
Isolierung & trockenes Gras, Laub (eichelfrei) & 10--15~cm Schicht \\
Wand-Flechtwerk & Weide, Hasel-Ruten & senkrechte Pfosten, waagerechte Ruten \\
Anbau-Start & Rhizom-St\"ucke von Quecke, Topinambur-Resten & 30~cm Reihen \\
Hochbeet & Wurzelgrube-Erde, Kompost, Gr\"unabfall & 3 Schichten \\
\end{longtable}

\begin{konzept}{8.1 -- Schilf- und Gras-Dach: B\"undel und Lagen}
\textbf{Definition:} Ein Dach \"uberlebt den Winter nur in Lagen: jede Lage
\"uberlappt die vorherige um zwei Drittel, so dass kein Wasser auf die
untere Schicht trifft.

\textbf{Dreifache Pr\"ufung vor der Aufnahme:}
\begin{schritte}
\item Ernte im Winter: trockene Halme, mattgelb, ohne Blattmassen.
\item B\"undel von Daumendicke binden mit Zwirn aus Konzept 7.2 -- ein
      Bund deckt etwa 10~cm Firstlinie.
\item Erste Lage an der Traufe festbinden, jede Lage \"uberlappt die
      vorherige um zwei Drittel; St\"arke mind.\ 20~cm Gesamtaufbau (Faustwert
      -- \"ortlich pr\"ufen nach Regenh\"aufigkeit).
\end{schritte}

\textbf{Dreifache Bewertung nach bestandener Pr\"ufung:}
\begin{schritte}
\item Probe-Regen mit 2~Litern Wasser auf 1~m\textsuperscript{2}: unterste
      Lage bleibt trocken?
\item B\"undel fest -- kein B\"undel l\"asst sich mit der Hand abziehen?
\item Dachkante gerade, \"Uberlappung \"uberall gleich?
\end{schritte}

\textbf{Grenzen:} Ein Grasdach braucht regelm\"a\ss{}ige Pflege und trocknet
nach Regen nur langsam -- in sehr regenreichen Lagen \"ortlich pr\"ufen und
h\"oheren Aufbau planen. Werkzeuge dazu in Band 4 (Unterkunft).
\end{konzept}

\begin{konzept}{8.2 -- Der Wildgarten: Rhizome setzen statt s\"aen}
\textbf{Definition:} St\"arke- und Knollengew\"achse werden im Herbst \"uber
Rhizom- und Knollenst\"ucke vermehrt -- ohne Saatgut, ohne Ger\"at, mit
h\"oherer Erfolgsquote als Aussaat.

\textbf{Dreifache Pr\"ufung vor der Aufnahme:}
\begin{schritte}
\item Stand w\"ahlen: mind.\ 6~Stunden Licht, kein Staun\"asse -- Test:
      Grube nach Tab.\ 4.1 graben, Wasser einlaufen lassen; nach 24~Stunden
      abgelaufen, dann tauglich.
\item Rhizom-St\"ucke ausw\"ahlen: je St\"uck mind.\ zwei Augen (sichtbare
      Knospen), frisch geschnitten, keine F\"aulstellen.
\item Setzen im Herbst oder Fr\"uhjahr: 10--15~cm tief, Abstand 30~cm in
      der Reihe, Reihenabstand 50~cm.
\end{schritte}

\textbf{Dreifache Bewertung nach bestandener Pr\"ufung:}
\begin{schritte}
\item Nach 4~Wachen Erdauswurf sichtbar (Triebe)?
\item Erste Ernte unter Konzept 4.1-Mengenregeln?
\item Fl\"ache markiert in Vorlage A.8 (Grundriss-Skizze)?
\end{schritte}

\textbf{Grenzen:} Ohne Pflege (Konkurrenz zur\"uckdr\"angen, Wassern in
Trockenphasen) bleibt der Ertrag unter dem der Wildwiese -- der Wildgarten
ist eine Erg\"anzzung, kein Acker-Ersatz.
\end{konzept}

\begin{figure}[ht]
\centering
\includesvg[width=\textwidth]{illustrationen/abb-8-1}
\caption{Abb.\ 8.1 -- Der Wildgarten: Gruben-Test und Rhizom-Setzung}
\end{figure}

\begin{baustein}
Merksatz: Ein Dach in Lagen \"uberlappt um zwei Drittel -- jede Stelle dreifach
gedeckt. Der Wildgarten wird gesetzt, nicht ges\"at.
\end{baustein}

\section{Kapitel-Checkliste: Dach-Pflanzen und Anbau}

\begin{checkliste}
\item Ich habe Dachmaterial nur im Winter und trocken geerntet.
\item Ich habe Daumendicke B\"undel mit eigenem Zwirn gebunden.
\item Ich habe jede Lage um zwei Drittel \"uberlappen lassen und die
      Wasserprobe durchgef\"uhrt.
\item Ich habe den Gruben-Staun\"asse-Test vor dem Setzen durchgef\"uhrt.
\item Ich habe Rhizom-St\"ucke mit zwei Augen in 10--15~cm gesetzt.
\item Ich habe die Fl\"ache in Vorlage A.8 skizziert.
\end{checkliste}

% =====================================================================
\chapter{Pilze und Kalender: die Randtechnik und die Jahres-Uhr}
% =====================================================================

\section{Pilze: eine Randtechnik mit hohem Risiko}

\begin{stand}
Status: Pilze sind in dieser Reihe Rand-Technik. Sie liefern Kalorien, aber
keine \"uberlebenskritische Menge -- das Risiko einer t\"odlichen
Verwechslung ist gegen\"uber Wildgem\"use unverh\"altnism\"a\ss{}ig hoch.
Anf\"anger sammeln keine R\"ohrlingspilze und keine Lamellenpilze, solange
Konzept 9.1 nicht bestanden ist.
\end{stand}

\begin{konzept}{9.1 -- Die Pilz-Einbahnregel}
\textbf{Definition:} Es gibt genau zwei sichere Pilz-Gruppen f\"ur
Nicht-Profis: die R\"ohren-Pilze mit klar bestimmbaren Merkmalen und keine
anderen -- Lamellenpilze bleiben au\ss{}en vor.

\textbf{Dreifache Pr\"ufung vor der Aufnahme:}
\begin{schritte}
\item Unterseite pr\"ufen: R\"ohren statt Lamellen -- nur Steinpilz-artige
      und R\"ohrlinge weiter pr\"ufen.
\item Merkmals-Kette nach Konzept 2.1 vollst\"andig: Hutrand, R\"ohrenfarbe,
      Stielnetz, Fleischfarbe am Schnitt.
\item Doppelter Ausschluss: jeder giftige Doppelg\"anger der gew\"ahlten Art
      einzeln gepr\"uft und schriftlich ausgeschlossen (Vorlage A.3).
\end{schritte}

\textbf{Dreifache Bewertung nach bestandener Pr\"ufung:}
\begin{schritte}
\item Erste Portion unter 30~g gekocht, 24-Stunden-Reaktion?
\item Keine unbestimmte Frucht in der Sammelt\"ute -- auch nicht als
      \glqq Anhang\grqq{}?
\item Jede Pilzmahlzeit vollst\"andig durcherhitzt (kein Rohgenuss)?
\end{schritte}

\textbf{Grenzen:} Auch unter R\"ohren-Pilzen gibt es bittere und
magenreizende Arten -- die Grenze der eigenen Ausbildung bleibt real. Im
Zweifel gilt der Merksatz des Bandes: wegwerfen ist kostenlos.
\end{konzept}

\begin{longtable}{p{40mm}p{40mm}p{50mm}}
\caption{Tab.\ 9.1 -- Pilz-Gruppen und ihre Zulassung}\\
\toprule
Gruppe & Zulassung & Begr\"undung \\
\midrule
\endfirsthead
\caption[]{Tab.\ 9.1 -- Pilz-Gruppen (Fortsetzung)}\\
\toprule
Gruppe & Zulassung & Begr\"undung \\
\midrule
\endhead
\bottomrule
\endlastfoot
R\"ohren-Pilze, bestimmt & Nach Konzept 9.1 & klare Merkmale, wenige
t\"odliche Doppelg\"anger \\
Lamellenpilze allgemein & f\"ur Nicht-Profis gesperrt & viele t\"odliche
Arten, \"ahnliche Habitate \\
R\"ohrlinge mit rotem Stiel & gesperrt & Verwechslung mit
Gallen-R\"ohrlingen h\"aufig \\
Alle rohen Pilze & gesperrt & auch essbare Arten roh unvertr\"aglich \\
\end{longtable}

\begin{konzept}{9.2 -- Die Jahres-Uhr: zw\"olf Sammel-Fenster}
\textbf{Definition:} Der Sammel-Kalender ordnet jeder Jahreszeit die
Pflanzenarbeit zu -- er h\"angt ausgedruckt als Vorlage A.9 am Lagerplatz
und wird nach jedem Monat abgehakt.

\textbf{Dreifache Pr\"ufung vor der Aufnahme:}
\begin{schritte}
\item Trage die \"ortlichen Fenster (erste Bl\"ute, erste Frucht) in
      Vorlage A.9 ein -- siehe \"ortlich pr\"ufen, da Klima schwankt.
\item Pr\"ufe jeden Monat das anstehende Fenster gegen die Konzepte der
      Kapitel 3--5.
\item Hake nach jedem Monat ab und notiere Abweichungen.
\end{schritte}

\textbf{Dreifache Bewertung nach bestandener Pr\"ufung:}
\begin{schritte}
\item Alle 12~Fenster nach einem Jahr ausgef\"ullt?
\item Mindestens 3~Fenster um mehr als 2~Wochen abweichend notiert und
      f\"ur das Folgejahr korrigiert?
\item Kalender mit Anhang C (\"Ubungsjahr) verzahnt?
\end{schritte}

\textbf{Grenzen:} Der Kalender ist eine Planungshilfe, kein Gesetz --
das Fenster entscheidet die Pflanze, nicht das Datum.
\end{konzept}

\begin{figure}[ht]
\centering
\includesvg[width=\textwidth]{illustrationen/abb-9-1}
\caption{Abb.\ 9.1 -- Die Jahres-Uhr: zw\"olf Fenster in vier Quartalen}
\end{figure}

\begin{baustein}
Merksatz: Pilze sind Zugabe, nicht Grundlage. Ein unbestimmter Pilz ist ein
toter Pilz -- in den M\"ull, nicht in die Pfanne.
\end{baustein}

\section{Kapitel-Checkliste: Pilze und Kalender}

\begin{checkliste}
\item Ich habe keine Lamellenpilze gesammelt, solange Konzept 9.1 nicht
      bestanden ist.
\item Ich habe jeden Pilz mit vollst\"andiger Merkmalskette und schriftlichem
      Doppelg\"anger-Ausschluss bestimmt.
\item Ich habe keine unbestimmte Frucht in der T\"ute gelassen.
\item Ich habe alle Pilze vollst\"andig durcherhitzt.
\item Ich habe die Jahres-Uhr (Vorlage A.9) ausgef\"ullt und monatlich
      abgehakt.
\item Ich habe Abweichungen notiert und f\"ur das Folgejahr korrigiert.
\end{checkliste}
